import re
pairs=[]
for txt in users:
 for n in range(1,4):
  m=re.search(rf'Demo pair {n} input \((\d+)x(\d+)\):\n(.*?)\nDemo pair {n} output \((\d+)x(\d+)\):\n(.*?)(?=\n\nSame instance|\Z)',txt,re.S)
  if m:
   h,w=int(m.group(1)),int(m.group(2)); ih=[list(map(int,l.split())) for l in m.group(3).splitlines()]
   oh=int(m.group(4));ow=int(m.group(5)); out=[list(map(int,l.split())) for l in m.group(6).strip().splitlines()]
   pairs.append((n,ih,out,(h,w,oh,ow)))
print([(n,len(ig),set(map(len,ig)),len(og),set(map(len,og)),dims) for n,ig,og,dims in pairs])
